package com.local.release.config;

import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import javax.sql.DataSource;
import java.sql.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class EnumSchemaMigrationTest {
  private DriverManagerDataSource source(){return new DriverManagerDataSource("jdbc:h2:mem:enum-"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");}
  @Test void expandsAllAffectedEnumsRetainsRowsDefaultsNullabilityIdentityAndUnknownValues()throws Exception{
    var ds=source();try(Connection c=ds.getConnection();Statement s=c.createStatement()){
      s.execute("create table app_service(id bigint generated by default as identity primary key, service_type enum('BACKEND','FRONTEND','LEGACY''CUSTOM') default 'BACKEND' not null, name varchar(100))");
      s.execute("insert into app_service(service_type,name) values('FRONTEND','original'),('LEGACY''CUSTOM','retained')");
      s.execute("create table release_task(id bigint generated by default as identity primary key, status enum('CANCELLED','FAILED','PENDING','RUNNING','SUCCESS') default 'PENDING' not null, current_step enum('GIT_PULL','BUILD_JAR'))");
      s.execute("insert into release_task(status,current_step) values('SUCCESS','BUILD_JAR')");
      s.execute("create table release_step(id bigint generated by default as identity primary key, step_type enum('GIT_PULL','BUILD_JAR') not null)");s.execute("insert into release_step(step_type) values('BUILD_JAR')");
      s.execute("create table runtime_operation(id bigint generated by default as identity primary key, status enum('SUCCESS','FAILED') not null)");s.execute("insert into runtime_operation(status) values('SUCCESS')");
    }
    Map<String,String> before=columnProperties(ds,"APP_SERVICE","SERVICE_TYPE");new EnumSchemaMigration(ds).customize(new HashMap<>());new EnumSchemaMigration(ds).customize(new HashMap<>());
    assertThat(columnProperties(ds,"APP_SERVICE","SERVICE_TYPE")).isEqualTo(before);
    try(Connection c=ds.getConnection();Statement s=c.createStatement()){
      try(ResultSet r=s.executeQuery("select id,service_type,name from app_service order by id")){assertThat(r.next()).isTrue();assertThat(r.getLong(1)).isEqualTo(1);assertThat(r.getString(2)).isEqualTo("FRONTEND");assertThat(r.getString(3)).isEqualTo("original");assertThat(r.next()).isTrue();assertThat(r.getString(2)).isEqualTo("LEGACY'CUSTOM");assertThat(r.next()).isFalse();}
      s.execute("insert into app_service(service_type,name) values('FLUTTER_ANDROID','new')");s.execute("insert into app_service(name) values('default still works')");
      try(ResultSet r=s.executeQuery("select id,service_type from app_service order by id desc limit 1")){r.next();assertThat(r.getLong(1)).isEqualTo(4);assertThat(r.getString(2)).isEqualTo("BACKEND");}
      s.execute("insert into release_task(status,current_step) values('WAITING_CONFIRMATION','BUILD_AAB')");s.execute("insert into release_step(step_type) values('ARCHIVE_ARTIFACT')");s.execute("insert into runtime_operation(status) values('WAITING_CONFIRMATION')");
      s.execute("insert into release_task(status,current_step) values('SUCCESS','BUILD_APK')");s.execute("insert into release_step(step_type) values('VALIDATE_APK')");
      try(ResultSet r=s.executeQuery("select status,current_step from release_task where id=1")){r.next();assertThat(r.getString(1)).isEqualTo("SUCCESS");assertThat(r.getString(2)).isEqualTo("BUILD_JAR");}
    }
  }
  @Test void newDatabaseAndExistingVarcharColumnsAreSafeNoOps()throws Exception{
    var ds=source();EnumSchemaMigration migration=new EnumSchemaMigration(ds);migration.customize(new HashMap<>());
    try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("create table app_service(id bigint primary key, service_type varchar(30))");s.execute("insert into app_service values(1,'CUSTOM')");}migration.customize(new HashMap<>());
    try(Connection c=ds.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select service_type from app_service")){r.next();assertThat(r.getString(1)).isEqualTo("CUSTOM");}
  }
  @Test void failureAbortsStartupRatherThanAllowingAnUnusableApplication()throws Exception{
    DataSource ds=mock(DataSource.class);when(ds.getConnection()).thenThrow(new SQLException("connection unavailable"));assertThatThrownBy(()->new EnumSchemaMigration(ds).customize(new HashMap<>())).isInstanceOf(IllegalStateException.class).hasMessageContaining("停止启动");
  }
  @Test void enumMetadataParsingPreservesQuotedValuesAndRejectsUnknownSyntax()throws Exception{
    assertThat(EnumSchemaMigration.parseValues("ENUM('BACKEND', 'CUSTOM''VALUE', 'WITH,COMMA')")).containsExactly("BACKEND","CUSTOM'VALUE","WITH,COMMA");
    assertThatThrownBy(()->EnumSchemaMigration.parseValues("ENUM('BACKEND',unsafe)" )).isInstanceOf(SQLException.class);
  }
  private Map<String,String> columnProperties(DataSource ds,String table,String column)throws Exception{
    try(Connection c=ds.getConnection();ResultSet r=c.getMetaData().getColumns(null,"PUBLIC",table,column)){r.next();return Map.of("nullable",r.getString("IS_NULLABLE"),"default",r.getString("COLUMN_DEF"));}
  }
}
